 43 │ export function CarPage() {
 44 │   const scope = useSettings((s) => s.settings.defaultScope);
 45 │   const { selectedModelId, powertrain, setPowertrain } = useVehicleStore();
 46 │   const active = useMemo(() => getActiveVehicle(), [selectedModelId, powertrain]);
 47 │   const sourceMesh = getSourceMeshInfoById(selectedModelId);
 48 │   const availableParts = availablePartIds(powertrain, active.model);
 49 │   const subclasses = powertrainSubclasses(powertrain, active.model);
 50 │   const [view, setView] = useState<CarView>("exterior");
 51 │   const [selected, setSelected] = useState<string | null>(null);
 52 │   const [markerMenu, setMarkerMenu] = useState(initialMarkerMenu);
 53 │   const [preset, setPreset] = useState<CameraPreset>("front");
 54 │   const [presetNonce, setPresetNonce] = useState(0);
 55 │   const data = useCarRequirements();
 56 │   const reset = useReset(data.reload);
 57 │ 
 58 │   const [whyReqId, setWhyReqId] = useState<string | null>(null);
 59 │   const markerParts = selected ? [selected] : menuPartIds(markerMenu.active, subclasses);
 60 │ 
 61 │   const onMenuToggle = (id: string) => {
 62 │     const next = toggleMarkerMenu(markerMenu, id);
 63 │     setMarkerMenu(next);
 64 │     setSelected(null);
 65 │     if (next.active) setView(menuGroup(next.active) === "exterior" ? "exterior" : "interior");
 66 │   };
 67 │ 
 68 │   const emptyHint =
 69 │     data.error ??
 70 │     (data.loading
 71 │       ? "Loading requirements…"
 72 │       : "Run a flow with an Add to Car block to see its requirements here.");
 73 │ 
 74 │   return (
