 99 │             <Segmented options={VIEWS} value={view} onChange={setView} testIdPrefix="car-view-" />
100 │             <div className="flex items-center gap-1">
101 │               {PRESETS.map((p) => (
102 │                 <Button
103 │                   key={p.value}
104 │                   size="sm"
105 │                   variant={preset === p.value ? "secondary" : "ghost"}
106 │                   data-testid={`car-camera-${p.value}`}
107 │                   onClick={() => {
108 │                     setPreset(p.value);
109 │                     setPresetNonce((n) => n + 1);
110 │                   }}
111 │                 >
112 │                   {p.label}
113 │                 </Button>
114 │               ))}
115 │             </div>
116 │           </>
117 │         }
118 │         className="min-w-0 flex-1"
119 │         testId="car-page"
120 │       >
121 │         <div className="relative h-full">
122 │           <PowertrainSwitcher value={powertrain} onChange={setPowertrain} />
123 │           <CarViewer
124 │             modelId={selectedModelId}
125 │             powertrain={powertrain}
126 │             counts={data.counts}
127 │             markerParts={markerParts}
128 │             selected={selected}
129 │             view={view}
130 │             preset={preset}
131 │             presetNonce={presetNonce}
132 │             onSelect={setSelected}
133 │           />
134 │           <p className="pointer-events-none absolute bottom-3 left-4 text-xs text-muted">
135 │             Sketch: {active.model.name} ·{" "}
136 │             {sourceMesh
137 │               ? `Original exterior · standard schematic interior · ${POWERTRAINS.find((option) => option.value === powertrain)?.description}`
138 │               : `${POWERTRAINS.find((option) => option.value === powertrain)?.description} · schematic sketch`}{" "}
139 │             · drag to turn, scroll to zoom, click any part
140 │             {sourceMesh && (
141 │               <span className="pointer-events-auto block">
142 │                 Source:{" "}
143 │                 <a
144 │                   className="underline"
145 │                   href={sourceMesh.source.url}
146 │                   target="_blank"
147 │                   rel="noreferrer"
148 │                 >
149 │                   {sourceMesh.source.author}
150 │                 </a>
151 │                 {" · "}
152 │                 <a
153 │                   className="underline"
154 │                   href={sourceMesh.source.license}
155 │                   target="_blank"
156 │                   rel="noreferrer"
157 │                 >
158 │                   License
159 │                 </a>
160 │               </span>
