162 │           </p>
163 │         </div>
164 │       </Panel>
165 │       <Panel
166 │         title="Parts & requirements"
167 │         actions={
168 │           <Button
169 │             size="sm"
170 │             variant="danger"
171 │             data-testid="car-reset"
