218 │         )}
219 │         <PartPanel
220 │           selected={selected}
221 │           availableParts={availableParts}
222 │           subclasses={subclasses}
223 │           markerMenu={markerMenu}
224 │           onMenuToggle={onMenuToggle}
225 │           byPart={data.byPart}
226 │           counts={data.counts}
227 │           total={data.total}
228 │           emptyHint={emptyHint}
