237 │ /** Reset on the Car page: ask in place, then remove every requirement (`requirements.reset`). */
238 │ function useReset(reload: () => Promise<void>) {
239 │   const [asking, setAsking] = useState(false);
240 │   const [busy, setBusy] = useState(false);
241 │   const [message, setMessage] = useState<string | null>(null);
242 │   const [failed, setFailed] = useState(false);
243 │ 
244 │   const confirm = async () => {
245 │     setBusy(true);
246 │     try {
247 │       const { removed } = await api.requirements.reset();
248 │       setFailed(false);
249 │       setMessage(`Removed ${removed} requirement${removed === 1 ? "" : "s"}.`);
250 │       setAsking(false);
251 │     } catch (e) {
252 │       setFailed(true);
253 │       setMessage(`Reset failed: ${e instanceof Error ? e.message : String(e)}`);
254 │     } finally {
255 │       setBusy(false);
256 │       await reload();
257 │     }
258 │   };
259 │ 
260 │   return {
261 │     asking,
262 │     busy,
263 │     message,
264 │     failed,
265 │     ask: () => {
266 │       setMessage(null);
267 │       setAsking(true);
268 │     },
269 │     cancel: () => setAsking(false),
270 │     confirm,
271 │   };
272 │ }

