18 │ /** Cancelling ignores late replies: closing or retrying must never display stale evidence. */
19 │ export function loadRequirementDetail(
20 │   id: string,
21 │   get: (id: string) => Promise<RequirementDetail>,
22 │   publish: (state: DetailState) => void,
23 │ ): () => void {
24 │   let cancelled = false;
25 │   publish({ status: "loading" });
26 │   void Promise.resolve()
27 │     .then(() => get(id))
28 │     .then((value) => {
29 │       if (cancelled) return;
30 │       const detail = Detail.parse(value);
31 │       if (detail.requirement.id !== id || detail.versions.some((r) => r.id !== id)) {
32 │         throw new Error("The returned details do not match this requirement. Please retry.");
33 │       }
34 │       publish({ status: "ready", detail });
35 │     })
36 │     .catch((error: unknown) => {
37 │       if (cancelled) return;
38 │       publish({
39 │         status: "error",
40 │         message:
41 │           error instanceof z.ZodError
42 │             ? "The requirement details are incomplete or invalid. Please retry."
43 │             : error instanceof Error
44 │               ? error.message
45 │               : "Could not load the requirement details. Please retry.",
46 │       });
47 │     });
48 │   return () => {
49 │     cancelled = true;
50 │   };
51 │ }

