201 │ type InvokeKeys<T> = {
202 │   [K in keyof T]: T[K] extends (...args: never[]) => Promise<unknown> ? K : never;
203 │ }[keyof T];
204 │ 
205 │ /** What main must implement: every request/response method (event subscriptions excluded). */
206 │ export type ReqflowHandlers = {
207 │   [N in keyof ReqflowApi]: Pick<ReqflowApi[N], InvokeKeys<ReqflowApi[N]>>;
208 │ };
209 │ 
210 │ /** Every request/response method, by namespace. Preload allow-lists exactly these channels. */
211 │ export const IPC_INVOKE_METHODS = {
212 │   app: ["info"],
213 │   templates: ["list"],
214 │   blocks: ["preview"],
215 │   workflows: ["list", "get", "save", "remove"],
216 │   files: ["import"],
217 │   runs: [
218 │     "start",
219 │     "get",
220 │     "list",
221 │     "blockOutput",
222 │     "reviewSplitter",
223 │     "filterReviewState",
224 │     "reviewFilter",
225 │     "resume",
226 │     "cancel",
227 │   ],
228 │   requirements: ["list", "get", "edit", "decide", "reset"],
229 │   audit: ["list"],
230 │   research: ["agents", "providers", "configure", "test", "dataset"],
231 │   settings: ["get", "save", "secrets", "setSecret", "testSetup"],
232 │   reasoning: ["forRun", "latest", "forRequirement"],
233 │   exports: ["requirements", "research", "hilReport"],
234 │ } as const satisfies { [N in keyof ReqflowApi]: readonly InvokeKeys<ReqflowApi[N]>[] };
235 │ 
236 │ // Compile-time guard: adding a method to ReqflowApi without listing it above is a type error.
237 │ type Listed = { [N in keyof ReqflowApi]: (typeof IPC_INVOKE_METHODS)[N][number] };
238 │ type Unlisted = {
239 │   [N in keyof ReqflowApi]: Exclude<InvokeKeys<ReqflowApi[N]>, Listed[N]>;
240 │ }[keyof ReqflowApi];
241 │ export const IPC_METHODS_COMPLETE: [Unlisted] extends [never] ? true : Unlisted = true;
242 │ 
243 │ export type IpcNamespace = keyof typeof IPC_INVOKE_METHODS;
244 │ 
245 │ export function ipcChannel(namespace: string, method: string): string {
246 │   return `reqflow:${namespace}.${method}`;
247 │ }
248 │ 
249 │ export const IPC_INVOKE_CHANNELS: ReadonlySet<string> = new Set(
250 │   Object.entries(IPC_INVOKE_METHODS).flatMap(([ns, methods]) =>
251 │     methods.map((m) => ipcChannel(ns, m)),
252 │   ),
253 │ );
254 │ 
255 │ /** main → renderer push events. */
256 │ export const IPC_EVENTS = { runUpdate: "reqflow:event.run-update" } as const;
257 │ 
258 │ /** Every invoke resolves to this; the renderer client turns `ok: false` into a thrown ReqflowError. */
259 │ export type IpcResult<T> = { ok: true; value: T } | { ok: false; error: ApiError["error"] };
260 │ 
261 │ /** The only object the preload exposes on `window.reqflowBridge`. */
262 │ export interface ReqflowBridge {
263 │   invoke(channel: string, ...args: unknown[]): Promise<IpcResult<unknown>>;
264 │   onRunUpdate(listener: (run: WorkflowRun) => void): () => void;
265 │ }

